	coordination := []string{"remote_http_request", "Bash", "sleep", "list_conversation_proofs", "link_conversation_proofs", "list_task_execution_proofs", "list_tasks", "list_vps", "list_llm_profiles", "spawn_task", "get_task_graph", "get_task_node_detail", "list_task_findings", "get_task_worker_trace", "list_task_worker_traces", "search_task_worker_traces", "add_task_hint", "pause_task", "schedule_pause", "list_scheduled_pauses", "cancel_scheduled_pause", "list_assets", "list_companies", "get_finding_traffic"}
